* { box-sizing:border-box; }
html, body { margin:0; padding:0; height:100%; background:#0F172A; }
.wrap { height:100vh; display:flex; flex-direction:column; padding:14px 18px 16px; gap:12px;
  font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
  color:#e2e8f0; -webkit-font-smoothing:antialiased; }
.topbar { display:flex; align-items:center; justify-content:space-between; gap:16px; flex:none; }
.ttl { font-size:17px; font-weight:400; color:#94a3b8; }
.ttl b { color:#f8fafc; font-weight:700; }
.x { background:transparent; border:1px solid #334155; color:#94a3b8; width:32px; height:32px;
  border-radius:8px; cursor:pointer; font-size:16px; line-height:1; display:flex; align-items:center; justify-content:center; }
.x:hover { border-color:#ef5a5a; color:#f87171; }
.searchrow { flex:none; }
.search { position:relative; }
.search input { width:100%; background:#1e293b; border:1px solid #334155; border-radius:10px; color:#e2e8f0;
  font:inherit; font-size:14px; padding:11px 14px 11px 40px; outline:none; }
.search input::placeholder { color:#64748b; }
.search input:focus { border-color:#34d399; }
.search > svg { position:absolute; left:13px; top:50%; transform:translateY(-50%); }
.filters { flex:none; display:flex; flex-wrap:wrap; gap:12px 16px; align-items:flex-end;
  background:#131f30; border:1px solid #22303f; border-radius:12px; padding:14px 16px; }
.fld { display:flex; flex-direction:column; gap:5px; }
.fld > label { font-size:11px; font-weight:600; color:#94a3b8; letter-spacing:.01em; }
.fld select, .fld input { background:#1e293b; border:1px solid #334155; border-radius:8px; color:#e2e8f0;
  font:inherit; font-size:13px; padding:8px 10px; outline:none; min-width:150px; }
.fld select:focus, .fld input:focus { border-color:#34d399; }
.fld .rng { display:flex; align-items:center; gap:7px; color:#64748b; font-size:12px; }
.fld .rng input { min-width:96px; }
.fld.chk { flex-direction:row; align-items:center; gap:8px; padding-bottom:6px; }
.fld.chk input { min-width:0; width:16px; height:16px; accent-color:#34d399; }
.fld.chk label { order:2; }
.fld.clr { justify-content:flex-end; margin-left:auto; }
.fld.clr a { color:#60a5fa; font-size:13px; font-weight:600; cursor:pointer; text-decoration:none; padding-bottom:8px; }
.fld.clr a:hover { text-decoration:underline; }
#myGrid { flex:1 1 auto; min-height:0; }
.pager { flex:none; display:flex; align-items:center; justify-content:space-between; gap:12px; color:#94a3b8; font-size:13px; }
.pager .ctrls { display:flex; align-items:center; gap:10px; }
.pager label { color:#64748b; display:inline-flex; align-items:center; gap:6px; }
.pager button, .pager select { background:#1e293b; border:1px solid #334155; color:#e2e8f0;
  border-radius:8px; padding:6px 12px; font:inherit; font-size:13px; cursor:pointer; }
.pager select { padding:6px 8px; }
.pager button:disabled { opacity:.4; cursor:default; }
.pager button:not(:disabled):hover { border-color:#34d399; }
:root, .ag-theme-quartz, .ag-theme-alpine {
  --ag-background-color:#1e293b; --ag-foreground-color:#e2e8f0;
  --ag-header-background-color:#182234; --ag-header-foreground-color:#94a3b8;
  --ag-border-color:#273244; --ag-row-border-color:#273244;
  --ag-odd-row-background-color:#1b2636; --ag-row-hover-color:#243044;
  --ag-control-panel-background-color:#1e293b; --ag-menu-background-color:#1e293b;
  --ag-popup-background-color:#1e293b; --ag-subtle-text-color:#94a3b8;
  --ag-input-focus-border-color:#34d399;
}

