function __ubmDarkTheme() {
  try {
    if (typeof agGrid !== "undefined" && agGrid.themeQuartz && agGrid.colorSchemeDarkBlue) {
      return agGrid.themeQuartz.withPart(agGrid.colorSchemeDarkBlue);
    }
  } catch (e) { console.warn("[AG] dark theme unavailable", e); }
  return undefined;
}
function rowsOf(m) { return (m && Array.isArray(m.rows)) ? m.rows : []; }
function makeCols(data) {
  if (!data.length) return [];
  return Object.keys(data[0]).map(function (k) { return { headerName: k, field: k }; });
}
function el(id) { return document.getElementById(id); }
function setVal(id, v) { var e = el(id); if (e) e.value = (v == null ? "" : v); }
function getVal(id) { var e = el(id); return e ? e.value : ""; }

var gridApi = null;
var state = { page: 1, pageSize: 50, total: 0, search: "" };
var searchTimer = null, filtersBuilt = false, optsFilled = false;

function pageInfo() {
  var start = state.total === 0 ? 0 : (state.page - 1) * state.pageSize + 1;
  var end = Math.min(state.page * state.pageSize, state.total);
  return start.toLocaleString() + "–" + end.toLocaleString() + " of " + state.total.toLocaleString();
}
function syncFooter() {
  el("pinfo").textContent = pageInfo();
  var maxPage = Math.max(1, Math.ceil(state.total / state.pageSize));
  el("prev").disabled = state.page <= 1;
  el("next").disabled = state.page >= maxPage;
  var ps = el("psize"); if (ps) ps.value = String(state.pageSize);
}
function fillOptions(model) {
  var vs = (model && model.vendors) || [], us = (model && model.utilities) || [];
  if (!vs.length && !us.length) return;
  var v = el("f_vendor");
  if (v && v.options.length <= 1 && vs.length) {
    vs.forEach(function (o) { var opt = document.createElement("option"); opt.value = o.value; opt.textContent = o.label; v.appendChild(opt); });
  }
  var u = el("f_utility");
  if (u && u.options.length <= 1 && us.length) {
    us.forEach(function (o) { var opt = document.createElement("option"); opt.value = o.value; opt.textContent = o.label; u.appendChild(opt); });
  }
  optsFilled = true;
}
function collectFilters() {
  return {
    status: getVal("f_status") || "all",
    vendor: getVal("f_vendor"),
    billType: getVal("f_billtype"),
    utility: getVal("f_utility"),
    costFrom: getVal("f_costfrom"),
    costTo: getVal("f_costto"),
    invFrom: getVal("f_invfrom"),
    invTo: getVal("f_invto"),
    loadedFrom: getVal("f_loadedfrom"),
    loadedTo: getVal("f_loadedto"),
    includeDeleted: el("f_deleted") ? el("f_deleted").checked : false
  };
}
function applyFilters() {
  appsmith.updateModel({ filters: collectFilters() });
  appsmith.triggerEvent("onFilter");
}
function buildFilters(model) {
  if (filtersBuilt) return;
  filtersBuilt = true;
  fillOptions(model);
  var f = (model && model.f) || {};
  setVal("f_status", f.status || "all");
  setVal("f_vendor", f.vendor); setVal("f_billtype", f.billType); setVal("f_utility", f.utility);
  setVal("f_costfrom", f.costFrom); setVal("f_costto", f.costTo);
  setVal("f_invfrom", f.invFrom); setVal("f_invto", f.invTo);
  setVal("f_loadedfrom", f.loadedFrom); setVal("f_loadedto", f.loadedTo);
  if (el("f_deleted")) el("f_deleted").checked = !!f.includeDeleted;

  ["f_status","f_vendor","f_billtype","f_utility","f_deleted"].forEach(function (id) {
    var e = el(id); if (e) e.addEventListener("change", applyFilters);
  });
  ["f_costfrom","f_costto","f_invfrom","f_invto","f_loadedfrom","f_loadedto"].forEach(function (id) {
    var e = el(id); if (e) e.addEventListener("change", applyFilters);
  });
  el("clear").addEventListener("click", function () {
    setVal("f_status", "all"); setVal("f_vendor", ""); setVal("f_billtype", ""); setVal("f_utility", "");
    setVal("f_costfrom", ""); setVal("f_costto", ""); setVal("f_invfrom", ""); setVal("f_invto", "");
    setVal("f_loadedfrom", ""); setVal("f_loadedto", "");
    if (el("f_deleted")) el("f_deleted").checked = false;
    if (el("q")) el("q").value = "";
    appsmith.updateModel({ filters: collectFilters(), search: "" });
    appsmith.triggerEvent("onFilter");
  });
  el("close").addEventListener("click", function () { appsmith.triggerEvent("onClose"); });
  el("prev").addEventListener("click", function () { if (state.page > 1) goPage(state.page - 1); });
  el("next").addEventListener("click", function () { goPage(state.page + 1); });
  el("psize").addEventListener("change", function () {
    state.pageSize = Number(this.value) || 50;
    appsmith.updateModel({ page: 1, pageSize: state.pageSize, search: state.search });
    appsmith.triggerEvent("onPaginate");
  });
  var q = el("q");
  if (q) q.addEventListener("input", function () {
    state.search = q.value;
    clearTimeout(searchTimer);
    searchTimer = setTimeout(function () {
      appsmith.updateModel({ page: 1, pageSize: state.pageSize, search: state.search });
      appsmith.triggerEvent("onSearch");
    }, 400);
  });
}
function goPage(page) {
  appsmith.updateModel({ page: page, pageSize: state.pageSize, search: state.search });
  appsmith.triggerEvent("onPaginate");
}
function render(model) {
  var rowData = rowsOf(model);
  state.page = Number(model && model.page) || 1;
  state.pageSize = Number(model && model.pageSize) || 50;
  state.total = Number(model && model.total) || 0;
  var c = el("cust"); if (c) c.textContent = (model && model.customerName) ? model.customerName : "UBM Demo";
  var opts = {
    columnDefs: makeCols(rowData), rowData: rowData, theme: __ubmDarkTheme(),
    pagination: false, defaultColDef: { sortable: true, resizable: true, filter: true, menuTabs: ["filterMenuTab"] },
    animateRows: true, popupParent: document.body, onGridReady: function (p) { gridApi = p.api; }
  };
  var d = el("myGrid"); d.innerHTML = ""; gridApi = agGrid.createGrid(d, opts);
  syncFooter();
}
function whenAgReady(cb) {
  if (typeof agGrid !== "undefined") { cb(); return; }
  var n = 0, t = setInterval(function () {
    if (typeof agGrid !== "undefined" || ++n > 120) { clearInterval(t); cb(); }
  }, 50);
}
appsmith.onReady(function () {
  buildFilters(appsmith.model);
  whenAgReady(function () { render(appsmith.model); });
  appsmith.onModelChange(function (m) {
    if (!optsFilled) fillOptions(m);
    whenAgReady(function () { render(m); });
  });
});

